Item.method_code:
const dialogParams = {
	type: 'SearchDialog',
	itemtypeName: 'Form'
};
const dialogResult = await ArasModules.MaximazableDialog.show('iframe', dialogParams).promise;
if (!dialogResult || !dialogResult.itemID) {
	return;
}

const actions = options.getActions();
const { defaultLanguageCode } = options.getState();
const label = dialogResult.keyed_name;
const image = '../images/TabDefault.svg';
const relatedItemProps = {
	label,
	[`label@aras.lang.${defaultLanguageCode}`]: label,
	image,
	additional_data: { formId: dialogResult.itemID }
};
const relatedItem = actions.addRelatedItem(relatedItemProps);

const adminRole = {
	id: '2618D6F5A90949BAA7E920D1B04C7EE1',
	keyedName: 'Administrators'
};
const relationshipItemProps = {
	related_id: relatedItem.id,
	'role@aras.id': adminRole.id,
	'role@aras.keyed_name': adminRole.keyedName
};
const relationshipItem = actions.addRelationshipItem(relationshipItemProps);

actions.selectItem(relationshipItem.id);
